PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS "Affiliate" ("id" TEXT PRIMARY KEY NOT NULL,"name" TEXT NOT NULL,"code" TEXT NOT NULL UNIQUE,"phone" TEXT,"email" TEXT,"isActive" BOOLEAN NOT NULL DEFAULT true,"clicks" INTEGER NOT NULL DEFAULT 0,"createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" DATETIME NOT NULL);
CREATE TABLE IF NOT EXISTS "Program" ("id" TEXT PRIMARY KEY NOT NULL,"name" TEXT NOT NULL UNIQUE,"slug" TEXT NOT NULL UNIQUE,"description" TEXT NOT NULL,"price" INTEGER NOT NULL,"commissionOverride" INTEGER,"active" BOOLEAN NOT NULL DEFAULT true);
CREATE TABLE IF NOT EXISTS "Lead" ("id" TEXT PRIMARY KEY NOT NULL,"name" TEXT NOT NULL,"phone" TEXT NOT NULL,"city" TEXT NOT NULL,"notes" TEXT,"source" TEXT NOT NULL DEFAULT 'DIRECT',"status" TEXT NOT NULL DEFAULT 'LEAD_BARU',"registrationValue" INTEGER,"paymentVerifiedAt" DATETIME,"createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" DATETIME NOT NULL,"programId" TEXT NOT NULL,"affiliateId" TEXT,FOREIGN KEY("programId") REFERENCES "Program"("id") ON DELETE RESTRICT ON UPDATE CASCADE,FOREIGN KEY("affiliateId") REFERENCES "Affiliate"("id") ON DELETE SET NULL ON UPDATE CASCADE);
CREATE TABLE IF NOT EXISTS "Commission" ("id" TEXT PRIMARY KEY NOT NULL,"amount" INTEGER NOT NULL,"status" TEXT NOT NULL DEFAULT 'PENDING',"generatedAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,"approvedAt" DATETIME,"paidAt" DATETIME,"affiliateId" TEXT NOT NULL,"leadId" TEXT NOT NULL UNIQUE,FOREIGN KEY("affiliateId") REFERENCES "Affiliate"("id") ON DELETE RESTRICT ON UPDATE CASCADE,FOREIGN KEY("leadId") REFERENCES "Lead"("id") ON DELETE RESTRICT ON UPDATE CASCADE);
CREATE TABLE IF NOT EXISTS "LeadActivity" ("id" TEXT PRIMARY KEY NOT NULL,"type" TEXT NOT NULL,"message" TEXT NOT NULL,"createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,"leadId" TEXT NOT NULL,FOREIGN KEY("leadId") REFERENCES "Lead"("id") ON DELETE RESTRICT ON UPDATE CASCADE);
CREATE TABLE IF NOT EXISTS "ReferralClick" ("id" TEXT PRIMARY KEY NOT NULL,"refCode" TEXT NOT NULL,"sessionId" TEXT,"createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,"affiliateId" TEXT NOT NULL,FOREIGN KEY("affiliateId") REFERENCES "Affiliate"("id") ON DELETE RESTRICT ON UPDATE CASCADE);
CREATE TABLE IF NOT EXISTS "AppSetting" ("id" TEXT PRIMARY KEY NOT NULL,"commissionMethod" TEXT NOT NULL DEFAULT 'FIXED',"fixedAmount" INTEGER NOT NULL DEFAULT 75000,"percentage" REAL NOT NULL DEFAULT 10,"triggerOnPayment" BOOLEAN NOT NULL DEFAULT true);
